from pathlib import Path
R=Path('/PATH/TO/transmissions-from-alpha-centauri');a='/art/reviews/xenon-072/'
css='body{margin:0;background:#19191e;color:#eee7df;font:16px/1.6 system-ui}header,section{padding:24px 3vw}p{max-width:1000px}a{color:#efbc91}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{width:100%;display:block}figcaption{padding:8px 0}@media(max-width:800px){.grid{grid-template-columns:1fr}}'
def fig(src,label):return f'<figure><a href="{src}"><img src="{src}" alt="{label}"></a><figcaption>{label}</figcaption></figure>'
p=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>072 · Windows and architectural refinements</title><style>{css}</style><header><h1>072 · Windows and architectural refinements</h1><p>Glazing reflection test; a 45° cantilever return; duct-metal vent slats; warm rust on the marked middle gallery; thicker chamfered ends on the sloping shoulder.</p><p><a href="#details">Before / after details</a> · <a href="{a}scene.blend">Editable Blender scene</a></p></header><section>'+fig(a+'render.png','072 · full scene')+'</section><section id="details"><div class="grid">'+fig('/art/reviews/xenon-071/right.png','071 · before')+fig(a+'right.png','072 · architecture refinements and reflection test')+'</div></section><section><p>Window reflections use native scene reflection captures and sharply reflective tinted glass. Lower foreground panes show structure; upper panes largely read as broad sky color. This remains a reflection study: brightness and contrast need artistic calibration before calling the glass finished.</p></section></html>'
(R/'prototype/review-072.html').write_text(p);(R/'prototype/index.html').write_text(p)
